package main

import (
	"bytes"
	"context"
	"encoding/json"
	"errors"
	"io"
	"net"
	"net/http"
	"strings"
	"sync"
	"time"

	"github.com/gorilla/websocket"
	zlog "github.com/rs/zerolog/log"
)

// The channel is the single WebSocket between an app and the server (PLAN
// §2.2): commands, observations, events and settings all go through it.
//
// Handshake: header X-Eria-Terminal (secret generated by the app, required)
// and, once signed in, Authorization: Bearer <session token>.
// The app sends requests {id, op, …}; each gets one reply {id, result} or
// {id, error: {type, message}}. Values, events and status are pushed
// ({push: …}), starting with {push: "welcome", terminal, profile}.

// request is one message from the app; fields depend on the op.
type request struct {
	ID      json.RawMessage `json:"id"`
	Op      string          `json:"op"`
	Thing   string          `json:"thing,omitempty"`
	Name    string          `json:"name,omitempty"`  // property, action or event
	Value   json.RawMessage `json:"value,omitempty"` // value to write, action input, op argument
	Profile int64           `json:"profile,omitempty"`
	PIN     string          `json:"pin,omitempty"`
}

type reply struct {
	ID     json.RawMessage `json:"id"`
	Result any             `json:"result,omitempty"`
	Error  *opError        `json:"error,omitempty"`
}

// Error types the app reacts to (PLAN §2.2).
const (
	failOffline = "offline" // the Thing does not answer
	failRefused = "refused" // not allowed (profile, level, Thing)
	failTimeout = "timeout"
	failInvalid = "invalid" // unknown op, Thing or name, bad value
	failFailed  = "failed"  // the Thing answered with an error
)

type opError struct {
	Type       string `json:"type"`
	Message    string `json:"message"`
	RetryAfter int    `json:"retryAfter,omitempty"` // seconds, for a locked profile
}

func fail(kind, message string) *opError { return &opError{Type: kind, Message: message} }

// maxInflight bounds the requests an app runs at once.
const maxInflight = 16

type Channel struct {
	hub      *Hub
	auth     *Auth
	registry *Registry
}

// session is the state of one connection.
type session struct {
	ch       *Channel
	client   *client
	terminal string
	mu       sync.Mutex
	profile  *Profile
	token    string
	inflight chan struct{}
}

func (ch *Channel) ServeWS(w http.ResponseWriter, r *http.Request) {
	term, err := ch.auth.Identify(r.Header.Get("X-Eria-Terminal"))
	if err != nil {
		http.Error(w, err.Error(), http.StatusBadRequest)
		return
	}
	s := &session{ch: ch, terminal: term.ID, inflight: make(chan struct{}, maxInflight)}
	if token := bearer(r); token != "" {
		if p, ok := ch.auth.Session(token); ok {
			s.profile, s.token = &p, token
		}
	}
	conn, err := upgrader.Upgrade(w, r, nil)
	if err != nil {
		return // Upgrade already answered the request
	}
	s.client = ch.hub.attach(term.ID)
	go ch.hub.writeLoop(conn, s.client)
	ch.hub.push(s.client, map[string]any{"push": "welcome", "terminal": term, "profile": s.profile})
	s.readLoop(conn)
	ch.hub.drop(s.client)
}

func (s *session) readLoop(conn *websocket.Conn) {
	conn.SetReadLimit(maxClientMsg)
	conn.SetReadDeadline(time.Now().Add(pongWait))
	conn.SetPongHandler(func(string) error { return conn.SetReadDeadline(time.Now().Add(pongWait)) })
	for {
		var req request
		if err := conn.ReadJSON(&req); err != nil {
			var syntax *json.SyntaxError
			if errors.As(err, &syntax) {
				continue // ponytail: a malformed frame is dropped without reply
			}
			return
		}
		select {
		case s.inflight <- struct{}{}:
			go func() {
				defer func() { <-s.inflight }()
				result, err := s.handle(req)
				if err != nil {
					result = nil
				}
				s.ch.hub.push(s.client, reply{ID: req.ID, Result: result, Error: err})
			}()
		default:
			s.ch.hub.push(s.client, reply{ID: req.ID, Error: fail(failInvalid, "too many requests at once")})
		}
	}
}

// level is the access level of the connection: the profile's, or 9.
func (s *session) level() int {
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.profile == nil {
		return notSignedIn
	}
	return s.profile.Level
}

func (s *session) handle(req request) (any, *opError) {
	auth := s.ch.auth
	switch req.Op {
	// --- Session ---
	case "profiles":
		list, err := auth.Profiles()
		for i := range list {
			list[i].Role = "" // the sign-in screen only needs names
		}
		return list, internal(err)
	case "login":
		token, wait, err := auth.Login(req.Profile, req.PIN)
		switch {
		case errors.Is(err, errLocked):
			return nil, &opError{Type: failRefused, Message: err.Error(), RetryAfter: int(wait.Seconds()) + 1}
		case err != nil:
			return nil, fail(failRefused, errBadPIN.Error())
		}
		p, _ := auth.Session(token)
		s.mu.Lock()
		s.profile, s.token = &p, token
		s.mu.Unlock()
		return map[string]any{"token": token, "profile": p}, nil
	case "logout":
		s.mu.Lock()
		auth.Logout(s.token)
		s.profile, s.token = nil, ""
		s.mu.Unlock()
		return true, nil
	case "reportType":
		var detected string
		json.Unmarshal(req.Value, &detected)
		return true, invalid(auth.ReportType(s.terminal, detected))

	// --- Services ---
	case "services":
		return s.ch.registry.Services(), nil
	case "contexts":
		list, err := auth.Contexts()
		return list, internal(err)
	case "read":
		td, p, err := s.property(req)
		if err != nil {
			return nil, err
		}
		return callThing(td, http.MethodGet, href(p.Forms, "readproperty"), nil)
	case "write":
		if s.level() >= notSignedIn {
			return nil, fail(failRefused, "not allowed for this profile")
		}
		td, p, err := s.property(req)
		if err != nil {
			return nil, err
		}
		if !isWritable(td, req.Name) {
			return nil, fail(failRefused, "read-only property")
		}
		if len(req.Value) == 0 {
			return nil, fail(failInvalid, "no value")
		}
		return callThing(td, http.MethodPut, href(p.Forms, "writeproperty"), req.Value)
	case "invoke":
		if s.level() >= notSignedIn {
			return nil, fail(failRefused, "not allowed for this profile")
		}
		td, ok := s.ch.registry.Thing(req.Thing)
		a, exists := td.Actions[req.Name]
		if !ok || !exists {
			return nil, fail(failInvalid, "unknown Thing or action")
		}
		return callThing(td, http.MethodPost, href(a.Forms, "invokeaction"), req.Value)
	case "observe", "unobserve", "subscribe", "unsubscribe":
		k := feedKey{req.Thing, kindProperty, req.Name}
		if req.Op == "subscribe" || req.Op == "unsubscribe" {
			k.Kind = kindEvent
		}
		if strings.HasPrefix(req.Op, "un") {
			s.ch.hub.unfollow(s.client, k)
			return true, nil
		}
		if err := s.ch.hub.follow(s.client, k); err != nil {
			return nil, err
		}
		return true, nil
	}

	// --- Administration (level 0) ---
	if s.level() != 0 {
		return nil, fail(failRefused, "unknown op, or not allowed for this profile")
	}
	switch req.Op {
	case "terminals":
		list, err := auth.Terminals()
		return list, internal(err)
	case "configureTerminal":
		var in TerminalChange
		if json.Unmarshal(req.Value, &in) != nil {
			return nil, fail(failInvalid, "bad terminal settings")
		}
		t, err := auth.ConfigureTerminal(in)
		if err != nil {
			return nil, invalid(err)
		}
		s.ch.hub.broadcast(t.ID, map[string]any{"push": "terminal", "terminal": t})
		return t, nil
	case "forgetTerminal":
		var id string
		json.Unmarshal(req.Value, &id)
		if err := auth.ForgetTerminal(id); err != nil {
			return nil, internal(err)
		}
		s.ch.hub.disconnect(id)
		return true, nil
	case "setContexts":
		var list []Context
		if json.Unmarshal(req.Value, &list) != nil {
			return nil, fail(failInvalid, "bad contexts")
		}
		if err := auth.SetContexts(list); err != nil {
			return nil, invalid(err)
		}
		s.ch.hub.broadcast("", map[string]string{"push": "contexts-changed"})
		return true, nil
	case "hidden":
		list, err := auth.Hidden()
		return list, internal(err)
	case "setHidden":
		var list []string
		if json.Unmarshal(req.Value, &list) != nil {
			return nil, fail(failInvalid, "bad patterns")
		}
		if err := auth.SetHidden(list); err != nil {
			return nil, invalid(err)
		}
		s.ch.registry.SetHide(list) // the status watcher then pushes things-changed
		return true, nil
	}
	return nil, fail(failInvalid, "unknown op")
}

func (s *session) property(req request) (TD, Property, *opError) {
	td, ok := s.ch.registry.Thing(req.Thing)
	p, exists := td.Properties[req.Name]
	switch {
	case !ok || !exists:
		return td, p, fail(failInvalid, "unknown Thing or property")
	case len(p.UriVariables) > 0:
		// ponytail: properties with uriVariables (contexts isActive/{context})
		// aren't relayed; the "actives" array covers them for now.
		return td, p, fail(failInvalid, "uriVariables not supported")
	}
	return td, p, nil
}

// callThing is the single path from the apps to the Things: the place where
// the person's token will be added once the auth service exists (lot 19).
func callThing(td TD, method, url string, body []byte) (json.RawMessage, *opError) {
	if url == "" {
		return nil, fail(failInvalid, "no HTTP form for this operation")
	}
	if len(body) > 0 && !json.Valid(body) {
		return nil, fail(failInvalid, "invalid JSON")
	}
	req, err := http.NewRequestWithContext(context.Background(), method, url, bytes.NewReader(body))
	if err != nil {
		return nil, fail(failInvalid, err.Error())
	}
	if method != http.MethodGet {
		req.Header.Set("Content-Type", "application/json") // required by go-wot
	}
	resp, err := upstream.Do(req)
	if err != nil {
		var netErr net.Error
		if errors.As(err, &netErr) && netErr.Timeout() {
			return nil, fail(failTimeout, "the Thing did not answer in time")
		}
		zlog.Warn().Err(err).Str("thing", td.ID).Msg("[channel:callThing] Thing unreachable")
		return nil, fail(failOffline, "Thing unreachable")
	}
	defer resp.Body.Close()
	data, _ := io.ReadAll(io.LimitReader(resp.Body, maxBody))
	switch {
	case resp.StatusCode == http.StatusUnauthorized || resp.StatusCode == http.StatusForbidden:
		return nil, fail(failRefused, strings.TrimSpace(string(data)))
	case resp.StatusCode >= 400 && resp.StatusCode < 500:
		return nil, fail(failInvalid, strings.TrimSpace(string(data)))
	case resp.StatusCode >= 500:
		return nil, fail(failFailed, strings.TrimSpace(string(data)))
	case len(bytes.TrimSpace(data)) == 0 || !json.Valid(data):
		return json.RawMessage("null"), nil
	}
	return data, nil
}

func internal(err error) *opError {
	if err == nil {
		return nil
	}
	zlog.Error().Err(err).Msg("[channel]")
	return fail(failFailed, "server error")
}

func invalid(err error) *opError {
	if err == nil {
		return nil
	}
	return fail(failInvalid, err.Error())
}
